// E8 3D Visualization Component (Canvas-based 2D projection)
const E8Visualization = ({ vertices }) => {
  const canvasRef = useRef(null);
  const animationRef = useRef(null);
  const rotationRef = useRef({ x: 0, y: 0 });

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !vertices || vertices.length === 0) return;
    
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;
    const centerX = width / 2;
    const centerY = height / 2;

    const draw = () => {
      ctx.fillStyle = "rgba(3, 3, 5, 0.2)";
      ctx.fillRect(0, 0, width, height);

      rotationRef.current.x += 0.005;
      rotationRef.current.y += 0.007;

      const cosX = Math.cos(rotationRef.current.x);
      const sinX = Math.sin(rotationRef.current.x);
      const cosY = Math.cos(rotationRef.current.y);
      const sinY = Math.sin(rotationRef.current.y);

      // Draw connections first
      ctx.strokeStyle = "rgba(212, 175, 55, 0.1)";
      ctx.lineWidth = 0.5;
      
      vertices.forEach((v1, i) => {
        vertices.slice(i + 1, i + 4).forEach((v2) => {
          // 3D rotation
          const x1 = v1.x * cosY - v1.z * sinY;
          const z1 = v1.x * sinY + v1.z * cosY;
          const y1 = v1.y * cosX - z1 * sinX;
          
          const x2 = v2.x * cosY - v2.z * sinY;
          const z2 = v2.x * sinY + v2.z * cosY;
          const y2 = v2.y * cosX - z2 * sinX;
          
          const scale = 80;
          ctx.beginPath();
          ctx.moveTo(centerX + x1 * scale, centerY + y1 * scale);
          ctx.lineTo(centerX + x2 * scale, centerY + y2 * scale);
          ctx.stroke();
        });
      });

      // Draw vertices
      vertices.forEach((v, i) => {
        // 3D rotation
        const x = v.x * cosY - v.z * sinY;
        const z = v.x * sinY + v.z * cosY;
        const y = v.y * cosX - z * sinX;
        
        const scale = 80;
        const screenX = centerX + x * scale;
        const screenY = centerY + y * scale;
        
        const colors = ["#D4AF37", "#00F0FF", "#9D00FF"];
        const color = colors[i % 3];
        
        ctx.beginPath();
        ctx.arc(screenX, screenY, 3, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.fill();
        
        // Glow effect
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.beginPath();
        ctx.arc(screenX, screenY, 2, 0, Math.PI * 2);
        ctx.fill();
        ctx.shadowBlur = 0;
      });

      animationRef.current = requestAnimationFrame(draw);
    };

    // Initial clear
    ctx.fillStyle = "#030305";
    ctx.fillRect(0, 0, width, height);
    
    draw();

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [vertices]);

  return (
    <div className="e8-container rounded-lg overflow-hidden flex items-center justify-center">
      <canvas
        ref={canvasRef}
        width={600}
        height={400}
        className="max-w-full h-auto"
        data-testid="e8-canvas"
      />
    </div>
  );
};

// Golden Spiral Canvas Component with Animation
const GoldenSpiral = ({ iterations = 12, scale = 1, animate = false }) => {
  const canvasRef = useRef(null);
  const animationRef = useRef(null);
  const progressRef = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;
    const centerX = width / 2;
    const centerY = height / 2;

    const draw = (progress = 1) => {
      ctx.clearRect(0, 0, width, height);

      // Draw golden spiral
      ctx.strokeStyle = "#D4AF37";
      ctx.lineWidth = 2;
      ctx.shadowColor = "#D4AF37";
      ctx.shadowBlur = 10;

      let a = 10 * scale;
      ctx.beginPath();
      
      const maxAngle = iterations * 90 * progress;
      for (let i = 0; i <= maxAngle; i++) {
        const angle = (i * Math.PI) / 180;
        const r = a * Math.pow(PHI, (2 * angle) / Math.PI);
        const x = centerX + r * Math.cos(angle);
        const y = centerY + r * Math.sin(angle);
        
        if (i === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      }
      
      ctx.stroke();

      // Draw golden rectangles
      ctx.strokeStyle = "rgba(212, 175, 55, 0.3)";
      ctx.lineWidth = 1;
      ctx.shadowBlur = 0;

      let size = 10 * scale;
      let x = centerX;
      let y = centerY;

      const rectCount = Math.floor(Math.min(iterations, 10) * progress);
      for (let i = 0; i < rectCount; i++) {
        ctx.strokeRect(x, y, size, size);
        const newSize = size * PHI;
        
        switch (i % 4) {
          case 0: x -= size; break;
          case 1: y -= newSize; break;
          case 2: x += size; break;
          case 3: y += size; break;
          default: break;
        }
        size = newSize;
      }
    };

    if (animate) {
      const animateSpiral = () => {
        progressRef.current += 0.01;
        if (progressRef.current > 1) progressRef.current = 0;
        draw(progressRef.current);
        animationRef.current = requestAnimationFrame(animateSpiral);
      };
      animateSpiral();
    } else {
      draw(1);
    }

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [iterations, scale, animate]);

  return (
    <canvas
      ref={canvasRef}
      width={600}
      height={600}
      className="max-w-full h-auto"
      data-testid="golden-spiral-canvas"
    />
  );
};

